<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Department; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class DepartmentController extends Controller { public function index(){return view('admin.departments.index');} public function data(){return response()->json(['data'=>Department::withCount('positions')->latest()->get()]);} public function show(Department $department){return response()->json($department);} public function store(Request $r){$d=Department::create($r->validate(['name'=>'required|max:100|unique:departments,name','description'=>'nullable','status'=>'required|in:active,inactive']));return response()->json(['message'=>'Department added successfully.','data'=>$d]);} public function update(Request $r,Department $department){$department->update($r->validate(['name'=>['required','max:100',Rule::unique('departments')->ignore($department->id)],'description'=>'nullable','status'=>'required|in:active,inactive']));return response()->json(['message'=>'Department updated successfully.']);} public function destroy(Department $department){if($department->positions()->exists())return response()->json(['message'=>'Cannot delete department with positions.'],422);$department->delete();return response()->json(['message'=>'Department deleted successfully.']);} }
